"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[1021],{3331:(a,n,e)=>{e.d(n,{R:()=>s,x:()=>u});var i=e(36672);const t={},r=i.createContext(t);function s(a){const n=i.useContext(r);return i.useMemo((function(){return"function"==typeof a?a(n):{...n,...a}}),[n,a])}function u(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:s(a.components),i.createElement(r.Provider,{value:n},a.children)}},45501:(a,n,e)=>{e.r(n),e.d(n,{assets:()=>k,contentTitle:()=>u,default:()=>m,frontMatter:()=>s,metadata:()=>i,toc:()=>g});const i=JSON.parse('{"id":"2023/03/28","title":"2023-03-28","description":"Perdebatan tentang Tabloid Berita dan Pengumpulan Data Windows","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/2023/03/28.md","sourceDirName":"2023/03","slug":"/2023/03/28","permalink":"/id/2023/03/28","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/id/docusaurus-plugin-content-docs//current/2023/03/28.md","tags":[],"version":"current","frontMatter":{"localized_date":"28 Maret 2023","top_news":"Perdebatan tentang Tabloid Berita dan Pengumpulan Data Windows"},"sidebar":"defaultSidebar","previous":{"title":"2023-03-29","permalink":"/id/2023/03/29"},"next":{"title":"2023-03-27","permalink":"/id/2023/03/27"}}');var t=e(23420),r=e(3331);const s={localized_date:"28 Maret 2023",top_news:"Perdebatan tentang Tabloid Berita dan Pengumpulan Data Windows"},u="2023-03-28",k={},g=[{value:"Perdebatan tentang Tabloid Berita dan Pengumpulan Data Windows",id:"perdebatan-tentang-tabloid-berita-dan-pengumpulan-data-windows",level:2},{value:"Kritikus Mengecam Icloud Keychain Apple karena Keterbatasan dan Pengalaman Pengguna yang Buruk",id:"kritikus-mengecam-icloud-keychain-apple-karena-keterbatasan-dan-pengalaman-pengguna-yang-buruk",level:2},{value:"Proposal Pengawasan Uni Eropa Melanggar Privasi, Diperlukan Solusi yang Lebih Baik",id:"proposal-pengawasan-uni-eropa-melanggar-privasi-diperlukan-solusi-yang-lebih-baik",level:2},{value:"Cftc Menuntut Binance untuk Perdagangan Ilegal dan Penghindaran Perusahaan",id:"cftc-menuntut-binance-untuk-perdagangan-ilegal-dan-penghindaran-perusahaan",level:2},{value:"Penggunaan Karyawan atas ChatGPT OpenAI Menimbulkan Kekhawatiran Keamanan.",id:"penggunaan-karyawan-atas-chatgpt-openai-menimbulkan-kekhawatiran-keamanan",level:2},{value:"Teknologi Kloning Suara AI Menimbulkan Kekhawatiran atas Penyalahgunaan dan Penipuan",id:"teknologi-kloning-suara-ai-menimbulkan-kekhawatiran-atas-penyalahgunaan-dan-penipuan",level:2},{value:"Kamera $40 milik John Glenn yang merevolusi fotografi luar angkasa.",id:"kamera-40-milik-john-glenn-yang-merevolusi-fotografi-luar-angkasa",level:2},{value:"Pengembang Mendiskusikan Pro dan Kontra Kerangka Kerja Svelte",id:"pengembang-mendiskusikan-pro-dan-kontra-kerangka-kerja-svelte",level:2},{value:"Safari 16.4: Fitur dan Ulasan Campuran",id:"safari-164-fitur-dan-ulasan-campuran",level:2},{value:"Pengguna Discussion Service Mendiskusikan Alternatif untuk GitHub selama Pemadaman",id:"pengguna-discussion-service-mendiskusikan-alternatif-untuk-github-selama-pemadaman",level:2}];function d(a){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-03-28",children:"2023-03-28"})}),"\n",(0,t.jsx)(n.h2,{id:"perdebatan-tentang-tabloid-berita-dan-pengumpulan-data-windows",children:"Perdebatan tentang Tabloid Berita dan Pengumpulan Data Windows"}),"\n",(0,t.jsxs)(n.p,{children:["Komentar di Hacker News membahas praktik Windows yang menampilkan berita tabloid dan pemberitahuan push, dengan beberapa mengkritik OS karena menyimpang dari tujuan intinya dan yang lain menunjukkan bahwa fitur tersebut ditujukan untuk melayani kepentingan bisnis Microsoft dengan mengumpulkan data pengguna untuk iklan bertarget. Para pengguna mengungkapkan pengalaman dan preferensi mereka yang berbeda dengan berbagai sistem operasi, termasuk Windows, Ubuntu, dan macOS, mendiskusikan masalah-masalah seperti stabilitas, kompatibilitas perangkat keras, dan kurva pembelajaran yang terkait dengan OS yang berbeda. Diskusi ini menyoroti sifat subjektif dalam memilih sistem operasi, dengan para pengguna menekankan pentingnya menemukan OS yang sesuai dengan kebutuhan dan preferensi mereka. Para komentator berbagi pengalaman mereka dalam menggunakan driver video eksklusif di Windows dan Linux, dengan beberapa lebih memilih Windows karena dukungan perangkat keras dan kemudahan penggunaan, sementara yang lain lebih memilih Linux karena keandalan dan dukungan komunitasnya. Para pengguna menunjukkan bahwa pembaruan Windows dapat menyebabkan masalah, seperti merusak sistem, mengurangi masa pakai baterai laptop, dan menciptakan kesengsaraan bootloader, sementara Linux dapat menjadi tidak stabil karena bug driver dan manajemen paket. Para pengguna menyarankan berbagai cara untuk memperbaiki masalah ini, termasuk menggunakan distribusi Linux yang berbeda. Diskusi berpusat pada kompatibilitas Linux dengan PC gaming, dengan beberapa orang berpendapat bahwa perbaikan telah dilakukan dalam beberapa tahun terakhir, sementara yang lain menunjukkan kesenjangan dalam dukungan dan kinerja game, terutama dengan langkah-langkah anti-cheat. Para pengguna mengungkapkan rasa frustrasi mereka dengan fitur-fitur dan iklan yang tidak diinginkan di Windows dan mendiskusikan berbagai cara untuk menyesuaikan dan mengontrol sistem operasi mereka atau beralih ke Linux atau konsol game. Perdebatan juga berkisar pada tingkat kompatibilitas Linux dengan game PC, dengan perbedaan pendapat tentang jumlah game yang berjalan dengan baik di Linux dan pentingnya untuk dapat memainkan game multipemain AAA secara online. Para pengguna mengkritik Windows karena berita tabloid yang mengganggu dan berkualitas rendah, yang menyebabkan frustrasi, dan mendiskusikan cara-cara untuk menonaktifkan atau membatasi jumlah berita utama yang tidak berguna atau menyesatkan pada papan widget. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35323121",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://www.tomshardware.com/news/windows-keeps-feeding-tabloid-news",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"kritikus-mengecam-icloud-keychain-apple-karena-keterbatasan-dan-pengalaman-pengguna-yang-buruk",children:"Kritikus Mengecam Icloud Keychain Apple karena Keterbatasan dan Pengalaman Pengguna yang Buruk"}),"\n",(0,t.jsxs)(n.p,{children:["Pengguna mengkritik iCloud Keychain Apple karena pengalaman pengguna yang buruk di Windows dan keterbatasan di Mac, seperti terikat dengan Safari dan kesulitan menemukan pengaturan Kata Sandi. Dilaporkan kurangnya integrasi dengan Rantai Kunci dan perangkat manajemen kata sandi Apple pada Windows, dan Passkeys dipandang menawarkan sedikit perbaikan. Beberapa pengguna berpendapat bahwa kurangnya manajemen kata sandi yang efisien merupakan bagian dari strategi Apple untuk mendorong pelanggan menggunakan pengelola kata sandi miliknya sendiri dalam Google Chrome. Apple mungkin akan mendapatkan keuntungan dengan memberikan bobot lebih pada perangkat lintas platform untuk mendukung pertumbuhan layanan. Secara keseluruhan, artikel ini menawarkan penilaian yang beragam pada sistem manajemen kata sandi Apple dan kompatibilitasnya dengan peramban lain. Para pengguna merekomendasikan pengelola kata sandi alternatif seperti Bitwarden atau 1Password, yang menawarkan fitur yang lebih tangguh, termasuk kemampuan untuk berbagi kata sandi di antara para anggota keluarga. Para pengguna menekankan pentingnya kebersihan kata sandi yang baik dan menyoroti manfaat kenyamanan dan keamanan menggunakan pengelola kata sandi. Beberapa pengguna menyarankan agar Apple merilis aplikasi mandiri untuk kata sandi, yang dapat diakses dari ikon toolbar di Safari dan dilengkapi dengan UI yang lengkap. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35329950",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://cabel.com/2023/03/27/apple-passwords-deserve-an-app/",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"proposal-pengawasan-uni-eropa-melanggar-privasi-diperlukan-solusi-yang-lebih-baik",children:"Proposal Pengawasan Uni Eropa Melanggar Privasi, Diperlukan Solusi yang Lebih Baik"}),"\n",(0,t.jsxs)(n.p,{children:['Sebuah proposal dari penyedia VPN Swedia yang akan memaksa para politisi di negara-negara Uni Eropa untuk tunduk pada pengawasan audio dan video 24 jam sehari dan tujuh hari seminggu tidak cocok untuk masyarakat demokratis dan melanggar hak privasi individu. Uni Eropa harus melihat langkah-langkah alternatif untuk meningkatkan transparansi dan akuntabilitas, seperti melobi reformasi dan memperluas akses ke informasi, alih-alih menerapkan langkah-langkah pengawasan yang ekstrem. Diskusi ini mencakup kurangnya kepercayaan terhadap politisi dan kebutuhan akan transparansi yang lebih besar dalam pengambilan keputusan mereka, dengan saran-saran mulai dari pengawasan pribadi hingga penerapan sistem yang mirip dengan tinjauan kode. Artikel ini membahas proses pemerintahan yang rusak dalam hal pemrosesan informasi dan mengusulkan solusi seperti transparansi yang lebih besar, pemantauan intensif terhadap para politisi, dan pengucilan gaya Athena melalui pemungutan suara publik. Usulan Uni Eropa untuk melarang enkripsi end-to-end dan mengharuskan perusahaan untuk memindai semua konten untuk mencari materi ilegal melanggar privasi dan kebebasan berbicara, menurut para kritikus. Konsep "Pintu di muka" dibahas dalam kaitannya dengan negosiasi politik dan potensi proposal kebijakan ekstremis untuk membuat proposal kebijakan yang lebih moderat tampak lebih enak. Defisit demokrasi di Uni Eropa menjadi perhatian beberapa pihak, dengan munculnya kekhawatiran tentang sifat otokratis Komisi Eropa dan pelemahan demokrasi ketika pemilih menjadi terlalu besar dan beragam. ',(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35321994",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://mullvad.net/en/chatcontrol",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"cftc-menuntut-binance-untuk-perdagangan-ilegal-dan-penghindaran-perusahaan",children:"Cftc Menuntut Binance untuk Perdagangan Ilegal dan Penghindaran Perusahaan"}),"\n",(0,t.jsxs)(n.p,{children:["omisi Perdagangan Berjangka Komoditi AS (CFTC) telah menggugat Binance karena mengizinkan pelanggan AS untuk memperdagangkan aset digital tanpa mendaftar ke agensi, dan untuk perdagangan ilegal dan penghindaran perusahaan. Binance diduga menggunakan struktur perusahaan yang kompleks bernama 'Tai Chi' untuk menghindari pengawasan regulasi AS. CEO Binance menyangkal tuduhan tersebut. Para komentator mengungkapkan skeptisisme tentang tindakan CFTC, dan beberapa mengkritik kurangnya kepatuhan perusahaan terhadap undang-undang anti pencucian uang. Kasus ini menimbulkan pertanyaan tentang motif regulator, dan oleh karena itu sebagian besar tanggapan di Hacker News secara skeptis mengkritik tindakan CFTC. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35327996",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://www.docdroid.net/60YAbCz/cftc-binance-pdf",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"penggunaan-karyawan-atas-chatgpt-openai-menimbulkan-kekhawatiran-keamanan",children:"Penggunaan Karyawan atas ChatGPT OpenAI Menimbulkan Kekhawatiran Keamanan."}),"\n",(0,t.jsxs)(n.p,{children:["Karyawan menggunakan ChatGPT OpenAI meskipun ada kekhawatiran atas keamanan data, dan beberapa bisnis membatasi penggunaannya sementara yang lain tidak. Ada kekhawatiran bahwa alat AI dapat menjadi target eksploitasi, dan keseimbangan antara produktivitas dan risiko harus dipertimbangkan. Kebocoran data dan risiko privasi menjadi perhatian dalam penggunaan ChatGPT untuk informasi perusahaan dan sensitif, dengan beberapa orang menyarankan perlunya versi pribadi. Larangan penggunaan ponsel pintar di area aman dan potensi risiko penggunaan alat AI seperti ChatGPT telah dibahas, dengan perlunya kehati-hatian dan langkah-langkah perlindungan data yang diakui. Perusahaan mulai menyarankan agar karyawan tidak menggunakan layanan AI generatif dan menyarankan perjanjian kerahasiaan dan kebijakan untuk mencegah paparan data. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35330438",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://www.darkreading.com/risk/employees-feeding-sensitive-business-data-chatgpt-raising-security-fears",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"teknologi-kloning-suara-ai-menimbulkan-kekhawatiran-atas-penyalahgunaan-dan-penipuan",children:"Teknologi Kloning Suara AI Menimbulkan Kekhawatiran atas Penyalahgunaan dan Penipuan"}),"\n",(0,t.jsx)(n.p,{children:'Teknologi kloning suara sedang dikembangkan dengan kemampuan untuk mengkloning suara hanya dengan beberapa detik input audio. Teknologi ini memiliki kasus penggunaan yang sah seperti membuat buku audio, tetapi menimbulkan kekhawatiran seputar penyalahgunaan untuk penipuan dan peniruan. Play.ht, sebuah perusahaan rintisan yang menawarkan layanan kloning suara, telah mengundang anggota masyarakat untuk mencoba versi beta teknologinya secara gratis. Play.ht mengklaim telah memiliki "banyak mitigasi untuk meningkatkan keamanan layanan ini" untuk mencegah penyalahgunaan. Para pengguna telah mendiskusikan potensi penggunaan dan implikasi dari teknologi ini, dengan para pendukungnya memuji potensinya untuk kebaikan dan para kritikus menyatakan keprihatinan tentang penyalahgunaan. Teknologi ini mungkin memerlukan regulasi untuk mencegah kasus penggunaan ilegal, termasuk pembuatan audio deepfake untuk tujuan jahat. Namun, beberapa orang berpendapat bahwa melarang semua penggunaan legal tidak akan mencegah penggunaan ilegal dan edukasi mungkin merupakan kunci untuk mengatasi potensi penipuan.'}),"\n",(0,t.jsx)(n.h2,{id:"kamera-40-milik-john-glenn-yang-merevolusi-fotografi-luar-angkasa",children:"Kamera $40 milik John Glenn yang merevolusi fotografi luar angkasa."}),"\n",(0,t.jsxs)(n.p,{children:["Penggunaan kamera seharga $40 oleh John Glenn selama mengorbit di sekitar bumi memaksa NASA untuk memikirkan kembali peran fotografi dalam misi luar angkasa. Artikel ini membahas inovasi yang dilakukan pada kamera Glenn oleh NASA, termasuk pegangan pistol dan mekanisme pelepasan kabel. Pentingnya kreativitas dan solusi berbiaya rendah dalam bidang teknologi disoroti dalam bagian komentar. Kamera Glenn memainkan peran penting dalam membentuk masa depan eksplorasi ruang angkasa dan menetapkan panggung untuk fotografi ruang angkasa. Kisah ini menekankan kekuatan bercerita dan pentingnya mengabadikan dan berbagi momen yang tak terlupakan, bahkan ketika momen tersebut bukan merupakan fokus utama sebuah proyek. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35328368",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://petapixel.com/2023/03/23/how-john-glenns-40-camera-forced-nasa-to-rethink-space-missions/",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"pengembang-mendiskusikan-pro-dan-kontra-kerangka-kerja-svelte",children:"Pengembang Mendiskusikan Pro dan Kontra Kerangka Kerja Svelte"}),"\n",(0,t.jsxs)(n.p,{children:["Svelte adalah kerangka kerja web yang populer untuk membangun antarmuka pengguna dengan struktur yang mudah digunakan, kinerja aplikasi yang cepat, dan mesin state yang teramati, tetapi ada tantangan potensial, termasuk kurva pembelajaran dengan pernyataan reaktif dan potensi bug dalam skala besar. Svelte menggunakan pendekatan berbasis kompiler yang dapat mengarah pada efisiensi lebih lanjut bagi para pengembang dengan kode boilerplate minimal dan manajemen state yang mudah, dengan kritik tentang menangani ketergantungan reaktif yang kompleks. Komentar-komentar membandingkan Svelte dengan kerangka kerja alternatif seperti React dan Vue, dengan pujian untuk pengalaman dan fungsionalitas pengembang yang lebih sederhana sementara juga membahas pentingnya kesederhanaan dan kejelasan dalam kode, dokumentasi yang dapat diandalkan, dan peralatan. Diskusi berpusat pada perbandingan framework JavaScript yang berbeda seperti React, Vue, dan Svelte, dengan tradeoff yang harus dipertimbangkan dan membuat pilihan yang tepat sangat penting. Pengguna menganggap Svelte menyenangkan untuk digunakan dan cocok untuk proyek-proyek perusahaan kecil dan besar, dengan potensi tantangan seputar label $ Svelte dan penanganan efek non-lokal. Artikel ini membahas pengalaman penulis menggunakan Svelte untuk membangun pembaca RSS pribadi, menyoroti keuntungan dari format komponen Svelte, penyimpanan bawaan, dan API dispatcher acara, tetapi juga menyebutkan sorotan seperti pernyataan reaktif ($), blok tunggu, dan API transisi dan animasi bawaan. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35324430",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://tyhopp.com/notes/thoughts-on-svelte",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"safari-164-fitur-dan-ulasan-campuran",children:"Safari 16.4: Fitur dan Ulasan Campuran"}),"\n",(0,t.jsxs)(n.p,{children:["Safari 16.4 menghadirkan fitur-fitur baru dan lebih baik, namun mendapat ulasan beragam dari para pengguna, sebagian memuji efisiensinya dan sebagian lagi mengkritik kurangnya kemampuan pemblokiran iklan yang canggih serta kompatibilitasnya dengan situs dan ekstensi. Pembaruan ini mencakup perbaikan bug, dukungan untuk standar Global Relay Apple dan notifikasi Web Push, serta FaceTime SharePlay dan codec ProRes Apple untuk iPhone 13 Pro dan 13 Pro Max. Safari 16.4 menambahkan dukungan untuk bagian video dari Web Codecs API, notifikasi push untuk Progressive Web Apps (PWA), dan iframe lazy loading, di antara peningkatan lainnya pada CSS, kueri media, dan Web API. Browser ini juga memperkenalkan peningkatan pada alat pengembangnya, memberikan fleksibilitas yang lebih besar untuk menyesuaikan ekstensi pemblokiran konten dan menawarkan perlindungan privasi yang lebih baik bagi pengguna dengan mode Lockdown. Sementara beberapa orang mengkritik kurangnya dukungan untuk Fullscreen dan Screen Orientation API, yang lain mengkhawatirkan dominasi satu mesin peramban di iOS. Secara keseluruhan, Safari 16.4 memberikan dukungan yang lebih baik bagi para pengembang dan pengalaman browsing yang lebih aman bagi para pengguna dengan berbagai perbaikan bug dan pembaruan polesan. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35329961",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://webkit.org/blog/13966/webkit-features-in-safari-16-4/",children:"Baca Teks Asli"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"pengguna-discussion-service-mendiskusikan-alternatif-untuk-github-selama-pemadaman",children:"Pengguna Discussion Service Mendiskusikan Alternatif untuk GitHub selama Pemadaman"}),"\n",(0,t.jsxs)(n.p,{children:["Pengguna mendiskusikan alternatif untuk GitHub selama pemadaman, termasuk opsi yang dihosting sendiri seperti Gerrit, Gitea, dan CodeCommit. Komentar lucu dibuat tentang Discussion Service sebagai pemeriksaan pilihan terakhir, dan lelucon tentang offline untuk menghindari peretasan. Para pengguna menyarankan ikon pemantau lalu lintas pada halaman utama untuk menunjukkan ketika ada sesuatu yang salah dengan GitHub, dan beberapa orang mempertanyakan keefektifan pesan kesalahan Git. Alternatif untuk remote Git disarankan, seperti bekerja melalui email melalui diffs atau menyiapkan sistem cadangan dengan instance git yang terpisah. Beberapa orang berspekulasi jika pemadaman GitHub baru-baru ini terkait dengan perubahan setelah akuisisi Microsoft, tetapi yang lain mengakui tantangan pengembangan yang bergerak cepat. Pengguna mengatasi risiko downtime dengan menyimpan kode mereka di hard drive, server perusahaan, atau GitLab, atau menggunakan alternatif seperti menyinkronkan repositori melalui SSH lokal atau jarak jauh atau menggunakan email untuk mengomunikasikan komitmen. Daftar nomor telepon internasional untuk berlangganan sistem manajemen insiden disediakan, dengan tarif data yang berlaku dan pengguna menyetujui kebijakan privasi dan persyaratan layanan. ",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35325709",children:"Diskusikan di Discussion Service"})," atau ",(0,t.jsx)(n.a,{href:"https://www.githubstatus.com/incidents/52z0j6phhnjs",children:"Baca Teks Asli"}),"."]})]})}function m(a={}){const{wrapper:n}={...(0,r.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(d,{...a})}):d(a)}}}]);